using namespace std;
int main() {
    int n, m;
    cin >> n >> m;
    vector<vector<int>> adj(n + 1);
    for (int i = 0; i < m; i++) { int u, v; cin >> u >> v; adj[u].push_back(v); adj[v].push_back(u); }
    vector<bool> seen(n + 1, false);
    int components = 0;
    for (int s = 1; s <= n; s++) {
        if (seen[s]) continue;
        components++;
        seen[s] = true;
        vector<int> stack = {s};
        while (!stack.empty()) {
            int u = stack.back(); stack.pop_back();
            for (int v : adj[u]) if (!seen[v]) { seen[v] = true; stack.push_back(v); }
        }
    }
    cout << components << "\n";
    return 0;
}

