#include <bits/stdc++.h>
using namespace std;
int main() {
    int R, C;
    cin >> R >> C;
    vector<string> g(R);
    for (auto& row : g) cin >> row;
    int islands = 0;
    for (int r = 0; r < R; r++)
        for (int c = 0; c < C; c++) {
            if (g[r][c] != '1') continue;
            islands++;
            g[r][c] = '0';
            vector<pair<int, int>> st = {{r, c}};
            while (!st.empty()) {
                auto [x, y] = st.back(); st.pop_back();
                int dx[] = {1, -1, 0, 0}, dy[] = {0, 0, 1, -1};
                for (int d = 0; d < 4; d++) {
                    int nx = x + dx[d], ny = y + dy[d];
                    if (nx >= 0 && nx < R && ny >= 0 && ny < C && g[nx][ny] == '1') { g[nx][ny] = '0'; st.push_back({nx, ny}); }
                }
            }
        }
    cout << islands << "\n";
    return 0;
}

