#include <bits/stdc++.h>
using namespace std;
int main() {
    int n, m;
    cin >> n >> m;
    vector<vector<int>> adj(n + 1);
    for (int i = 0; i < m; i++) { int u, v; cin >> u >> v; adj[u].push_back(v); adj[v].push_back(u); }
    vector<int> colour(n + 1, -1);
    bool ok = true;
    for (int s = 1; s <= n && ok; s++) {
        if (colour[s] != -1) continue;
        colour[s] = 0;
        queue<int> q;
        q.push(s);
        while (!q.empty() && ok) {
            int u = q.front(); q.pop();
            for (int v : adj[u]) {
                if (colour[v] == -1) { colour[v] = 1 - colour[u]; q.push(v); }
                else if (colour[v] == colour[u]) ok = false;
            }
        }
    }
    cout << (ok ? "YES" : "NO") << "\n";
    return 0;
}

#include <bits/stdc++.h>
using namespace std;
int main() {
    int n, m;
    cin >> n >> m;
    vector<vector<int>> out(n + 1);
    vector<int> indeg(n + 1, 0);
    for (int i = 0; i < m; i++) { int u, v; cin >> u >> v; out[u].push_back(v); indeg[v]++; }
    priority_queue<int, vector<int>, greater<int>> ready;
    for (int x = 1; x <= n; x++) if (indeg[x] == 0) ready.push(x);
    vector<int> order;
    while (!ready.empty()) {
        int u = ready.top(); ready.pop();
        order.push_back(u);
        for (int v : out[u]) if (--indeg[v] == 0) ready.push(v);
    }
    if ((int)order.size() < n) { cout << "IMPOSSIBLE\n"; return 0; }  // the rest are stuck on a cycle
    for (int i = 0; i < n; i++) cout << order[i] << (i + 1 < n ? " " : "\n");
    return 0;
}

#include <bits/stdc++.h>
using namespace std;
int main() {
    int n, m;
    cin >> n >> m;
    vector<vector<pair<int, long long>>> adj(n + 1);
    for (int i = 0; i < m; i++) { int u, v; long long w; cin >> u >> v >> w; adj[u].push_back({v, w}); adj[v].push_back({u, w}); }
    const long long INF = LLONG_MAX;
    vector<long long> dist(n + 1, INF);
    dist[1] = 0;
    priority_queue<pair<long long, int>, vector<pair<long long, int>>, greater<>> pq;
    pq.push({0, 1});
    while (!pq.empty()) {
        auto [d, u] = pq.top(); pq.pop();
        if (d > dist[u]) continue;  // stale entry
        for (auto [v, w] : adj[u]) if (d + w < dist[v]) { dist[v] = d + w; pq.push({dist[v], v}); }
    }
    for (int i = 1; i <= n; i++) cout << (dist[i] == INF ? -1 : dist[i]) << (i < n ? " " : "\n");
    return 0;
}

#include <bits/stdc++.h>
using namespace std;
vector<int> parent;
int find(int x) { while (parent[x] != x) { parent[x] = parent[parent[x]]; x = parent[x]; } return x; }
int main() {
    int n, m;
    cin >> n >> m;
    vector<tuple<long long, int, int>> edges(m);
    for (auto& [w, u, v] : edges) cin >> u >> v >> w;
    sort(edges.begin(), edges.end());
    parent.resize(n + 1);
    iota(parent.begin(), parent.end(), 0);
    long long total = 0;
    int used = 0;
    for (auto& [w, u, v] : edges) {
        int ru = find(u), rv = find(v);
        if (ru != rv) { parent[ru] = rv; total += w; used++; }
    }
    cout << (used == n - 1 ? total : -1) << "\n";
    return 0;
}

